<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {purchaseApi} from '@/api/purchases'
import type {PurchaseRecord} from '@/api/purchases'
const route=useRoute(),router=useRouter(),purchase=ref<PurchaseRecord|null>(null),loading=ref(true),busy=ref(false),error=ref('')
const money=(v:number)=>new Intl.NumberFormat('en-BD',{style:'currency',currency:'BDT'}).format((v||0)/100)
async function load(){try{const r=await purchaseApi.purchase(Number(route.params.id));purchase.value=r.data.data}catch(e:any){error.value=e?.response?.data?.message||'Could not load purchase.'}finally{loading.value=false}}
async function receive(){if(!confirm('Confirm goods received? This will add the quantities to warehouse stock.'))return;busy.value=true;try{const r=await purchaseApi.receive(Number(route.params.id));purchase.value=r.data.data}catch(e:any){error.value=e?.response?.data?.message||'Could not receive purchase.'}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="page"><header><div><small>PURCHASE MANAGEMENT</small><h1>{{purchase?.purchase_no||'Purchase details'}}</h1><p>Review order lines and receive inventory.</p></div><button class="light" @click="router.push({name:'purchases.index'})">Back</button></header><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="card">Loading purchase...</div><template v-else-if="purchase"><div class="grid"><div class="card"><small>SUPPLIER</small><h3>{{purchase.supplier?.name||'—'}}</h3><p>{{purchase.supplier?.company_name||''}}</p></div><div class="card"><small>WAREHOUSE</small><h3>{{purchase.warehouse?.name||'—'}}</h3></div><div class="card"><small>STATUS</small><h3 class="status">{{purchase.status}}</h3><p>{{purchase.received_at?'Received '+new Date(purchase.received_at).toLocaleString(): 'Not received yet'}}</p></div></div><div class="card table"><h3>Purchase items</h3><div class="scroll"><table><thead><tr><th>Product</th><th>SKU</th><th>Quantity</th><th>Unit cost</th><th>Total</th></tr></thead><tbody><tr v-for="i in purchase.items||[]" :key="i.id"><td><b>{{i.product_name}}</b><small>{{i.variant_name||'Default'}}</small></td><td>{{i.sku}}</td><td>{{i.quantity}}</td><td>{{money(i.unit_cost)}}</td><td>{{money(i.line_total)}}</td></tr></tbody></table></div><div class="totals"><p>Subtotal <b>{{money(purchase.subtotal)}}</b></p><p>Discount <b>{{money(purchase.discount_amount)}}</b></p><p>Tax <b>{{money(purchase.tax_amount)}}</b></p><h2>Grand total <strong>{{money(purchase.grand_total)}}</strong></h2></div><p v-if="purchase.note">{{purchase.note}}</p><button v-if="purchase.status==='draft'" :disabled="busy" @click="receive">{{busy?'Receiving...':'Confirm goods received'}}</button><p v-else class="received">Inventory receipt has been posted.</p></div></template></section></template>
<style scoped>
.page{color:#172033}.page header{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.page small{font-size:10px;color:#64748b;letter-spacing:1px;font-weight:800}.page h1{font-size:25px;margin:5px 0}.page p{font-size:12px;color:#64748b}.card{background:#fff;border:1px solid #e7ebf1;border-radius:13px;padding:18px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:15px}.grid h3{font-size:15px}.table h3{font-size:15px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-top:1px solid #edf0f4;font-size:12px}th{font-size:10px;color:#64748b}td small{display:block;color:#94a3b8}.totals{margin-left:auto;width:min(300px,100%)}.totals p,.totals h2{display:flex;justify-content:space-between;font-size:12px}.totals h2{font-size:16px;border-top:1px solid #e2e8f0;padding-top:12px}.page button{background:#172033;color:white;border:0;border-radius:8px;padding:11px 15px}.page .light{background:#fff;color:#334155;border:1px solid #dfe5ed}.status{color:#a16207}.received{color:#047857}.error{color:#be123c}.scroll{overflow:auto}@media(max-width:700px){.grid{grid-template-columns:1fr}}
</style>
